/*
 * Combined assertion binary for the two ported guards.
 * Compiled with AddressSanitizer: any out-of-bounds read aborts non-zero.
 * Exits 0 iff every positive and negative assertion passes.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef uint32_t u32;
typedef uint8_t u8;
#define CIPSO_V4_INV_LVL 0x80000000u

static int walk_new(const unsigned char *bitmap, u32 bitmap_len, u32 offset, u8 state)
{
	u32 bit_spot, byte_offset;
	unsigned char bitmask, byte;

	byte_offset = offset / 8;
	byte = bitmap[byte_offset];
	bit_spot = offset;
	bitmask = 0x80 >> (offset % 8);

	while (bit_spot < bitmap_len) {
		if ((state && (byte & bitmask) == bitmask) ||
		    (state == 0 && (byte & bitmask) == 0))
			return (int)bit_spot;
		if (++bit_spot >= bitmap_len)
			return -1;
		bitmask >>= 1;
		if (bitmask == 0) {
			byte = bitmap[++byte_offset];
			bitmask = 0x80;
		}
	}
	return -1;
}

struct lvlmap { u32 *cipso; u32 cipso_size; };

static int lvl_new(const struct lvlmap *m, u8 level)
{
	if ((level < m->cipso_size) &&
	    (m->cipso[level] < CIPSO_V4_INV_LVL))
		return 0;
	return -14; /* -EFAULT */
}

static int fails;

#define CHECK(cond) do { if (!(cond)) { printf("FAIL: %s\n", #cond); fails++; } } while (0)

int main(void)
{
	unsigned char *b;

	/* negative path: last bit not set -> must return -1 without over-read */
	b = malloc(1); b[0] = 0x00; CHECK(walk_new(b, 8, 0, 1) == -1); free(b);
	b = malloc(2); b[0] = 0x00; b[1] = 0x00; CHECK(walk_new(b, 16, 0, 1) == -1); free(b);
	/* positive paths: in-bounds matches preserved */
	b = malloc(1); b[0] = 0x01; CHECK(walk_new(b, 8, 0, 1) == 7); free(b);
	b = malloc(1); b[0] = 0x80; CHECK(walk_new(b, 8, 0, 1) == 0); free(b);
	b = malloc(1); b[0] = 0xFF; CHECK(walk_new(b, 8, 0, 0) == -1); free(b);
	/* negative path: out-of-range level rejected */
	{
		struct lvlmap m; u32 a[8]; int i;
		for (i = 0; i < 8; i++) a[i] = 0;
		m.cipso = a; m.cipso_size = 8;
		CHECK(lvl_new(&m, 200) == -14);
		CHECK(lvl_new(&m, 3) == 0);
	}
	if (fails) { printf("%d ASSERTION(S) FAILED\n", fails); return 1; }
	printf("ALL ASSERTIONS PASSED\n");
	return 0;
}

