typedef uint32_t u32;
typedef uint8_t u8;
#define CIPSO_V4_INV_LVL 0x80000000u

static int walk_new(const unsigned char *bitmap, u32 bitmap_len, u32 offset, u8 state)
{
	u32 bit_spot, byte_offset;
	unsigned char bitmask, byte;

	byte_offset = offset / 8;
	byte = bitmap[byte_offset];
	bit_spot = offset;
	bitmask = 0x80 >> (offset % 8);

	while (bit_spot < bitmap_len) {
		if ((state && (byte & bitmask) == bitmask) ||
		    (state == 0 && (byte & bitmask) == 0))
			return (int)bit_spot;
		if (++bit_spot >= bitmap_len)
			return -1;
		bitmask >>= 1;
		if (bitmask == 0) {
			byte = bitmap[++byte_offset];
			bitmask = 0x80;
		}
	}
	return -1;
}

struct lvlmap { u32 *cipso; u32 cipso_size; };

static int lvl_new(const struct lvlmap *m, u8 level)
{
	if ((level < m->cipso_size) &&
	    (m->cipso[level] < CIPSO_V4_INV_LVL))
		return 0;
	return -14; /* -EFAULT */
}

static int fails;

#define CHECK(cond) do { if (!(cond)) { printf("FAIL: %s\n", #cond); fails++; } } while (0)

int main(void)
{
