	b = malloc(1); b[0] = 0x00; CHECK(walk_new(b, 8, 0, 1) == -1); free(b);
	b = malloc(2); b[0] = 0x00; b[1] = 0x00; CHECK(walk_new(b, 16, 0, 1) == -1); free(b);
	/* positive paths: in-bounds matches preserved */
	b = malloc(1); b[0] = 0x01; CHECK(walk_new(b, 8, 0, 1) == 7); free(b);
	b = malloc(1); b[0] = 0x80; CHECK(walk_new(b, 8, 0, 1) == 0); free(b);
	b = malloc(1); b[0] = 0xFF; CHECK(walk_new(b, 8, 0, 0) == -1); free(b);
