/* ---- PRE-fix netlbl_bitmap_walk (reference-parent logic) ---- */
static int walk_old(const unsigned char *bitmap, u32 bitmap_len, u32 offset, u8 state)
{
	u32 bit_spot, byte_offset;
	unsigned char bitmask, byte;

	byte_offset = offset / 8;
	byte = bitmap[byte_offset];
	bit_spot = offset;
	bitmask = 0x80 >> (offset % 8);

	while (bit_spot < bitmap_len) {
		if ((state && (byte & bitmask) == bitmask) ||
		    (state == 0 && (byte & bitmask) == 0))
			return (int)bit_spot;
		bit_spot++;
		bitmask >>= 1;
		if (bitmask == 0) {
			byte = bitmap[++byte_offset];
			bitmask = 0x80;
		}
	}
	return -1;
}

